#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

static long long gcdll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long m;
    cin >> n >> m;

    vector<long long> a(n);
    vector<long double> p(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        p[i] = (long double)x / 100.0L;
    }

    // Remove useless numbers > m (they divide no number in [1..m])
    vector<long long> b;
    vector<long double> q;
    for (int i = 0; i < n; ++i) {
        if (a[i] <= m) {
            b.push_back(a[i]);
            q.push_back(p[i]);
        }
    }
    a = b;
    p = q;
    n = (int)a.size();

    // Merge equal values:
    // probability that value x is selected at least once:
    // 1 - product(1-p_i) over all occurrences of x
    map<long long, long double> mp_not;
    for (int i = 0; i < n; ++i) {
        if (!mp_not.count(a[i])) mp_not[a[i]] = 1.0L;
        mp_not[a[i]] *= (1.0L - p[i]);
    }

    vector<long long> vals;
    vector<long double> prob;
    for (auto &it : mp_not) {
        vals.push_back(it.first);
        prob.push_back(1.0L - it.second);
    }

    // Remove numbers that are multiples of a smaller number:
    // if x is selected, any multiple y is redundant because multiples of y
    // are already multiples of x.
    vector<pair<long long, long double>> items;
    for (int i = 0; i < (int)vals.size(); ++i) items.push_back({vals[i], prob[i]});
    sort(items.begin(), items.end());

    vector<long long> base;
    vector<long double> basep;
    for (auto &[x, pr] : items) {
        bool redundant = false;
        for (long long y : base) {
            if (x % y == 0) {
                redundant = true;
                break;
            }
        }
        if (!redundant) {
            base.push_back(x);
            basep.push_back(pr);
        }
    }

    int N = (int)base.size();

    // Expected count = sum_{t=1..m} P(t divisible by at least one selected number)
    // By linearity and inclusion-exclusion:
    // sum over non-empty subsets S:
    //   (-1)^{|S|+1} floor(m / lcm(S)) * prod_{i in S} p_i
    //
    // Enumerate subsets with pruning when lcm > m.
    long double ans = 0.0L;

    function<void(int, long long, long double, int)> dfs = [&](int idx, long long cur_lcm, long double cur_prob, int parity) {
        for (int i = idx; i < N; ++i) {
            long long g = gcdll(cur_lcm, base[i]);
            i128 nxt = (i128)cur_lcm / g * base[i];
            if (nxt > m) continue;
            long long nlcm = (long long)nxt;
            long double nprob = cur_prob * basep[i];
            long double add = (long double)(m / nlcm) * nprob;
            if (parity == 0) ans += add;
            else ans -= add;
            dfs(i + 1, nlcm, nprob, parity ^ 1);
        }
    };

    dfs(0, 1LL, 1.0L, 0);

    cout.setf(ios::fixed);
    cout << setprecision(12) << (double)ans << '\n';
    return 0;
}

#include <stdio.h>
#include <math.h>

long long gcd(long long a, long long b) {
    while (b) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b;
}

int main() {
    int n, m;
    scanf("%d", &n);
    int a[20];
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int p[20];
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);
    scanf("%d", &m);

    double prob[1<<n];
    prob[0] = 1.0;
    for (int i = 0; i < n; i++) {
        double p_select = p[i] / 100.0;
        double p_not = 1.0 - p_select;
        for (int mask = (1<<i)-1; mask >= 0; mask--) {
            prob[mask | (1<<i)] = prob[mask] * p_select;
            prob[mask] *= p_not;
        }
    }

    double expected = 0.0;
    for (int mask = 1; mask < (1<<n); mask++) {
        long long L = 1;
        int bits = 0;
        int overflow = 0;
        for (int i = 0; i < n; i++) {
            if (mask & (1<<i)) {
                bits++;
                L = lcm(L, a[i]);
                if (L > m) {
                    overflow = 1;
                    break;
                }
            }
        }
        if (overflow) continue;
        long long count = m / L;
        if (bits % 2 == 1) {
            expected += prob[mask] * count;
        } else {
            expected -= prob[mask] * count;
        }
    }

    printf("%.10f\n", expected);
    return 0;
}

