typedef long long ll;

static ll gcdll(ll a, ll b) {
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    int n;
    ll m;
    if (scanf("%d %lld", &n, &m) != 2) return 0;

    ll *a = (ll *)malloc(n * sizeof(ll));
    double *p = (double *)malloc(n * sizeof(double));
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);
    for (int i = 0; i < n; ++i) {
        ll x;
        scanf("%lld", &x);
        p[i] = x / 100.0;
    }

    double ans = 0.0;
    int total = 1 << n;

    for (int mask = 1; mask < total; ++mask) {
        ll lcm = 1;
        int bits = 0;
        double prob = 1.0;
        int ok = 1;

        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                bits++;
                prob *= p[i];
                ll g = gcdll(lcm, a[i]);
                ll t = lcm / g;
                if (t > m / a[i]) {
                    ok = 0;
                    break;
                }
                lcm = t * a[i];
                if (lcm > m) {
                    ok = 0;
                    break;
                }
            } else {
                prob *= (1.0 - p[i]);
            }
        }

        if (!ok || prob == 0.0) continue;

        ll cnt = m / lcm;
        if (bits & 1) ans += prob * cnt;
        else ans -= prob * cnt;
    }

    printf("%.10f\n", ans);

    free(a);
    free(p);
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        double[] p = new double[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble() / 100.0;
        }
        int m = sc.nextInt();

        double[] notProb = new double[m + 1];
        for (int x = 1; x <= m; x++) {
            notProb[x] = 1.0;
        }

        for (int i = 0; i < n; i++) {
            if (p[i] == 0.0) continue;
            double factor = 1.0 - p[i];
            for (int mult = a[i]; mult <= m; mult += a[i]) {
                notProb[mult] *= factor;
            }
        }

        double expected = 0.0;
        for (int x = 1; x <= m; x++) {
            expected += 1.0 - notProb[x];
        }

        System.out.printf("%.6f%n", expected);
    }
}

