import java.io.*;
import java.util.*;

/*
Expected count of integers x in [1..m] divisible by at least one selected ai.

Each ai is selected independently with probability pi/100.

For a fixed x, let S(x) = { i | ai divides x }.
Then:
  P(x is covered) = 1 - product over i in S(x) of (1 - pi/100)

Expected answer:
  sum_{x=1..m} P(x is covered)

Group equal ai values:
If several indices have same value d, the probability that at least one of them is selected is
  q[d] = 1 - product(1 - pi/100) over all ai=d
and only this grouped probability matters.

For fixed x, only divisors d of x among existing ai matter:
  P(not covered) = product_{d|x, d in A} (1 - q[d])

Let g[d] = 1 - q[d] = product(1 - pi/100) over all ai=d.

Then for each x:
  uncovered(x) = product_{d|x} g[d]   (for d present; absent means factor 1)

We need sum_x (1 - uncovered(x)).

Since m is the range, we can compute uncovered[x] by multiplying g[d] into all multiples of d.
Complexity O(m log m).
*/

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextInt();

        double[] prod = new double[m + 1];
        Arrays.fill(prod, 1.0);

        for (int i = 0; i < n; i++) {
            int p = fs.nextInt();
            if (a[i] <= m) {
                prod[a[i]] *= (100.0 - p) / 100.0;
            }
        }

        double[] uncovered = new double[m + 1];
        Arrays.fill(uncovered, 1.0);

        for (int d = 1; d <= m; d++) {
            double g = prod[d];
            if (g == 1.0) continue; // no such ai=d, or all p=0
            for (int x = d; x <= m; x += d) {
                uncovered[x] *= g;
            }
        }

        double ans = 0.0;
        for (int x = 1; x <= m; x++) {
            ans += 1.0 - uncovered[x];
        }

        System.out.printf(Locale.US, "%.10f%n", ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
